package com.grimyherbstopwatch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GrimyHerbStopwatchConfig.GROUP)
public interface GrimyHerbStopwatchConfig extends Config
{
    String GROUP = "grimyherbstopwatch";

    @ConfigItem(
        keyName = "showOverlay",
        name = "Show overlay",
        description = "Show the Grimy Herb Stopwatch session statistics overlay"
    )
    default boolean showOverlay()
    {
        return true;
    }
}

package com.grimyherbstopwatch;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class GrimyHerbStopwatchOverlay extends OverlayPanel
{
    private final GrimyHerbStopwatchPlugin plugin;
    private final GrimyHerbStopwatchConfig config;

    @Inject
    private GrimyHerbStopwatchOverlay(
        GrimyHerbStopwatchPlugin plugin,
        GrimyHerbStopwatchConfig config)
    {
        this.plugin = plugin;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay())
        {
            return null;
        }

        panelComponent.getChildren().add(
            TitleComponent.builder()
                .text("Grimy Herb Stopwatch")
                .build()
        );

        panelComponent.getChildren().add(
            LineComponent.builder()
                .left("Total herbs cleaned")
                .right(Integer.toString(plugin.getTotalHerbsCleaned()))
                .build()
        );

        panelComponent.getChildren().add(
            LineComponent.builder()
                .left("Average clean speed")
                .right(formatSpeed(plugin.getAverageSpeed()))
                .build()
        );

        panelComponent.getChildren().add(
            LineComponent.builder()
                .left("Top cleaning speed")
                .right(formatSpeed(plugin.getTopSpeed()))
                .build()
        );

        panelComponent.getChildren().add(
            LineComponent.builder()
                .left("Average accuracy")
                .right(formatPercent(plugin.getAverageAccuracy()))
                .build()
        );

        return super.render(graphics);
    }

    private static String formatSpeed(double speed)
    {
        return speed <= 0.0 ? "--" : String.format("%.2f herbs/s", speed);
    }

    private static String formatPercent(double accuracy)
    {
        return Double.isNaN(accuracy) ? "--" : String.format("%.2f%%", accuracy);
    }
}

package com.grimyherbstopwatch;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Grimy Herb Stopwatch",
    description = "Times grimy herb cleaning inventories and tracks cleaning speed and accuracy",
    tags = {"herblore", "herbs", "grimy", "cleaning", "stopwatch", "timer", "accuracy"}
)
public class GrimyHerbStopwatchPlugin extends Plugin
{
    private static final long INACTIVITY_NANOS = 15_000_000_000L;

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private GrimyHerbStopwatchOverlay overlay;

    private boolean bankOpen;
    private boolean runActive;
    private boolean sessionActive;

    private long runStartedAt;
    private long lastSuccessfulCleanAt;

    private int initialGrimyCount;
    private int runCleanedCount;

    private final Set<String> runHerbNames = new HashSet<>();
    private Map<String, Integer> previousGrimyCounts = new HashMap<>();
    private Map<String, Integer> previousCleanCounts = new HashMap<>();

    private int totalHerbsCleaned;
    private int completedRuns;
    private double totalAccuracy;
    private double totalSpeed;
    private double topSpeed;

    @Provides
    GrimyHerbStopwatchConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GrimyHerbStopwatchConfig.class);
    }

    @Override
    protected void startUp()
    {
        resetEverything();
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        resetEverything();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.BANKMAIN)
        {
            bankOpen = true;
            snapshotInventory();
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() != InterfaceID.BANKMAIN)
        {
            return;
        }

        bankOpen = false;
        beginRunFromCurrentInventory();
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() != InventoryID.INV)
        {
            return;
        }

        InventorySnapshot current = readInventory();

        if (!runActive)
        {
            previousGrimyCounts = current.grimyCounts;
            previousCleanCounts = current.cleanCounts;
            return;
        }

        int newlyCleaned = countSuccessfulCleans(current);

        if (newlyCleaned > 0)
        {
            runCleanedCount += newlyCleaned;
            totalHerbsCleaned += newlyCleaned;
            lastSuccessfulCleanAt = System.nanoTime();
        }

        if (bankOpen && countCleanHerbsRemoved(current) > 0)
        {
            finishRun();
        }

        previousGrimyCounts = current.grimyCounts;
        previousCleanCounts = current.cleanCounts;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!sessionActive || lastSuccessfulCleanAt == 0L)
        {
            return;
        }

        if (System.nanoTime() - lastSuccessfulCleanAt >= INACTIVITY_NANOS)
        {
            sessionActive = false;
            runActive = false;
            clearRunState();
        }
    }

    private void beginRunFromCurrentInventory()
    {
        InventorySnapshot snapshot = readInventory();

        if (snapshot.totalGrimy <= 0)
        {
            runActive = false;
            previousGrimyCounts = snapshot.grimyCounts;
            previousCleanCounts = snapshot.cleanCounts;
            return;
        }

        // A new cleaning session begins after the previous session timed out.
        if (!sessionActive)
        {
            resetSessionStats();
            sessionActive = true;
        }

        runHerbNames.clear();
        runHerbNames.addAll(snapshot.grimyCounts.keySet());

        initialGrimyCount = snapshot.totalGrimy;
        runCleanedCount = 0;
        runStartedAt = System.nanoTime();
        lastSuccessfulCleanAt = runStartedAt;

        previousGrimyCounts = snapshot.grimyCounts;
        previousCleanCounts = snapshot.cleanCounts;

        runActive = true;
    }

    private int countSuccessfulCleans(InventorySnapshot current)
    {
        int cleaned = 0;

        for (String herbName : runHerbNames)
        {
            int previousGrimy = previousGrimyCounts.getOrDefault(herbName, 0);
            int currentGrimy = current.grimyCounts.getOrDefault(herbName, 0);
            int grimyDecrease = Math.max(0, previousGrimy - currentGrimy);

            int previousClean = previousCleanCounts.getOrDefault(herbName, 0);
            int currentClean = current.cleanCounts.getOrDefault(herbName, 0);
            int cleanIncrease = Math.max(0, currentClean - previousClean);

            // Require both sides of the conversion. This avoids counting a
            // dropped/traded grimy herb or an unrelated clean herb pickup.
            cleaned += Math.min(grimyDecrease, cleanIncrease);
        }

        return cleaned;
    }

    private int countCleanHerbsRemoved(InventorySnapshot current)
    {
        int removed = 0;

        for (String herbName : runHerbNames)
        {
            int previousClean = previousCleanCounts.getOrDefault(herbName, 0);
            int currentClean = current.cleanCounts.getOrDefault(herbName, 0);
            removed += Math.max(0, previousClean - currentClean);
        }

        return removed;
    }

    private void finishRun()
    {
        if (!runActive || initialGrimyCount <= 0)
        {
            return;
        }

        long finishedAt = System.nanoTime();
        double seconds = Math.max(0.001, (finishedAt - runStartedAt) / 1_000_000_000.0);

        double accuracy = 100.0 * runCleanedCount / initialGrimyCount;
        double speed = runCleanedCount / seconds;

        totalAccuracy += accuracy;
        totalSpeed += speed;
        topSpeed = Math.max(topSpeed, speed);
        completedRuns++;

        runActive = false;
        clearRunState();
    }

    private InventorySnapshot readInventory()
    {
        Map<String, Integer> grimyCounts = new HashMap<>();
        Map<String, Integer> cleanCounts = new HashMap<>();
        int totalGrimy = 0;

        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
        {
            return new InventorySnapshot(grimyCounts, cleanCounts, 0);
        }

        for (Item item : inventory.getItems())
        {
            if (item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }

            ItemComposition composition = itemManager.getItemComposition(item.getId());
            String itemName = composition.getName();
            if (itemName == null)
            {
                continue;
            }

            String normalized = itemName.trim().toLowerCase(Locale.ROOT);

            if (normalized.startsWith("grimy ") && normalized.length() > 6)
            {
                String cleanName = normalized.substring(6);
                grimyCounts.merge(cleanName, item.getQuantity(), Integer::sum);
                totalGrimy += item.getQuantity();
            }
            else
            {
                cleanCounts.merge(normalized, item.getQuantity(), Integer::sum);
            }
        }

        return new InventorySnapshot(grimyCounts, cleanCounts, totalGrimy);
    }

    private void snapshotInventory()
    {
        InventorySnapshot snapshot = readInventory();
        previousGrimyCounts = snapshot.grimyCounts;
        previousCleanCounts = snapshot.cleanCounts;
    }

    private void clearRunState()
    {
        initialGrimyCount = 0;
        runCleanedCount = 0;
        runStartedAt = 0L;
        runHerbNames.clear();
    }

    private void resetSessionStats()
    {
        totalHerbsCleaned = 0;
        completedRuns = 0;
        totalAccuracy = 0.0;
        totalSpeed = 0.0;
        topSpeed = 0.0;
        lastSuccessfulCleanAt = 0L;
    }

    private void resetEverything()
    {
        bankOpen = false;
        runActive = false;
        sessionActive = false;
        previousGrimyCounts = new HashMap<>();
        previousCleanCounts = new HashMap<>();
        clearRunState();
        resetSessionStats();
    }

    int getTotalHerbsCleaned()
    {
        return totalHerbsCleaned;
    }

    double getAverageSpeed()
    {
        return completedRuns == 0 ? 0.0 : totalSpeed / completedRuns;
    }

    double getTopSpeed()
    {
        return topSpeed;
    }

    double getAverageAccuracy()
    {
        return completedRuns == 0 ? Double.NaN : totalAccuracy / completedRuns;
    }

    private static final class InventorySnapshot
    {
        private final Map<String, Integer> grimyCounts;
        private final Map<String, Integer> cleanCounts;
        private final int totalGrimy;

        private InventorySnapshot(
            Map<String, Integer> grimyCounts,
            Map<String, Integer> cleanCounts,
            int totalGrimy)
        {
            this.grimyCounts = grimyCounts;
            this.cleanCounts = cleanCounts;
            this.totalGrimy = totalGrimy;
        }
    }
}

package com.grimyherbstopwatch;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GrimyHerbStopwatchPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(GrimyHerbStopwatchPlugin.class);
        RuneLite.main(args);
    }
}
